using Microsoft.EntityFrameworkCore;
using UniversityCafeteriaManagement.Models.DatabaseFirst;
namespace UniversityCafeteriaManagement.Data;
public class CafeteriaDbContext(DbContextOptions<CafeteriaDbContext> options) : DbContext(options)
{
    public DbSet<Category> Categories => Set<Category>(); public DbSet<Supplier> Suppliers => Set<Supplier>(); public DbSet<Product> Products => Set<Product>(); public DbSet<PurchaseOrder> PurchaseOrders => Set<PurchaseOrder>(); public DbSet<PurchaseOrderItem> PurchaseOrderItems => Set<PurchaseOrderItem>();
    protected override void OnModelCreating(ModelBuilder b) { b.Entity<Category>().HasIndex(x => x.Name).IsUnique(); b.Entity<Product>().ToTable(t => { t.HasCheckConstraint("CK_Products_Price", "[Price] >= 0"); t.HasCheckConstraint("CK_Products_Quantity", "[Quantity] >= 0"); }); b.Entity<Product>().Property(x => x.Price).HasPrecision(10,2); b.Entity<PurchaseOrderItem>().ToTable(t => { t.HasCheckConstraint("CK_PurchaseOrderItems_Quantity", "[Quantity] > 0"); t.HasCheckConstraint("CK_PurchaseOrderItems_UnitPrice", "[UnitPrice] >= 0"); }); b.Entity<PurchaseOrderItem>().Property(x => x.UnitPrice).HasPrecision(10,2); b.Entity<PurchaseOrder>().ToTable(t => t.HasCheckConstraint("CK_PurchaseOrders_Status", "[Status] IN ('Pending','Received','Cancelled')")); b.Entity<PurchaseOrder>().Property(x => x.Status).HasDefaultValue("Pending"); b.Entity<Product>().HasOne(x=>x.Category).WithMany(x=>x.Products).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict); b.Entity<Product>().HasOne(x=>x.Supplier).WithMany(x=>x.Products).HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Restrict); b.Entity<PurchaseOrder>().HasOne(x=>x.Supplier).WithMany(x=>x.PurchaseOrders).HasForeignKey(x=>x.SupplierId).OnDelete(DeleteBehavior.Restrict); b.Entity<PurchaseOrderItem>().HasOne(x=>x.PurchaseOrder).WithMany(x=>x.Items).HasForeignKey(x=>x.PurchaseOrderId).OnDelete(DeleteBehavior.Cascade); b.Entity<PurchaseOrderItem>().HasOne(x=>x.Product).WithMany(x=>x.PurchaseOrderItems).HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict); }
}
